PADRES = [
 dict(id='P01', slug='crisostomo', name='Juan Crisóstomo', dates='c. 347–407', img=f'{HB}/H1/dl/img_chrysostom.jpg', pos='50% 15%',
  role='Presbítero en Antioquía y arzobispo de Constantinopla (398–404). Gran predicador griego; conservamos sus homilías sobre Hebreos, sobre Mateo y «Contra los judíos».',
  why='Comenta Hebreos 10:26-31 línea a línea y también la parábola del trigo y la cizaña: responde a las dos mitades del vídeo.',
  credit='Mosaico bizantino del tímpano norte de Santa Sofía (Estambul). Wikimedia Commons, «Johnchrysostom.jpg», dominio público.',
  img_note='Iconografía tradicional, no un retrato en vida.',
  foot='Citas: Hom. 20 y 13 sobre Hebreos (NPNF1-14); Hom. 46 sobre Mateo (NPNF1-10). Traducción al español mía desde el inglés de dominio público; no he leído el griego. Fechas aproximadas.',
  ojo='«Contra los judíos» (Hom. 1 §9) dice que a quien siga «una fe ajena» no se le mate ni se tome venganza, sino que se le libere de su error; pero en §6 de la misma obra usa imágenes violentas contra los judíos («aptos para el matadero»). No uso esa obra a favor de nadie: su tono es el de un orador que acusa, no el de una norma.',
  quotes=[
   dict(theme=['H'], es='«El que ha despreciado la ley de Moisés muere sin misericordia, por el testimonio de dos o tres testigos. “Sin misericordia”, dice: de modo que allí no hay perdón ni compasión, aunque la ley sea de Moisés; pues él estableció la mayor parte de ella. ¿Qué es “por dos o tres”? Si dos o tres daban testimonio, quiere decir, [[k:enseguida sufrían el castigo]].»',
        work='Homilías sobre la Epístola a los Hebreos, hom. 20', date='finales del s. IV o inicios del s. V · griego', ref='Hom. 20, §3 (comentario a Heb 10:28); numeración NPNF1-14',
        trans=NPNF, url='https://www.newadvent.org/fathers/240220.htm',
        clar='Crisóstomo explica Heb 10:28 como un hecho del pasado («daban testimonio… sufrían el castigo»): no manda a los cristianos aplicar esa pena. La comparación del v. 29 («cuánto mayor castigo») la aplica a los bautizados que vuelven a pecar, y en §1 de la misma homilía dice qué les espera: «la excomunión y el fuego», no una ejecución.',
        ojo='No nombra ninguna pena humana para el «castigo mayor» del v. 29. Tampoco encontré en esa homilía que use el v. 28 para pedir la muerte de nadie.'),
   dict(theme=['D'], es='«Allí se escribieron preceptos —“Haz esto” y “No hagas aquello”— que solo se mandaban y no daban fuerza interior. Pero la Esperanza no es así. […] ¿Era entonces inútil la Ley? Era útil, y de gran utilidad; pero [[k:para hacer perfectos a los hombres no servía]]. […] Todo eran figuras, todo sombras: la circuncisión, el sacrificio, el sábado.»',
        work='Homilías sobre la Epístola a los Hebreos, hom. 13', date='finales del s. IV o inicios del s. V · griego', ref='Hom. 13 (comentario a Heb 7:19, «la Ley nada perfeccionó»)',
        trans=NPNF, url='https://www.newadvent.org/fathers/240213.htm',
        clar='La Ley mandaba («Haz esto, no hagas aquello») pero no daba fuerza interior. Crisóstomo no la declara mala —«de gran utilidad»— sino incapaz de perfeccionar: lo que Hebreos llama sombra. Es la distinción «Ley útil pero no plena» que sostiene la respuesta al vídeo.'),
   dict(theme=['N', 'X'], es='«Porque [[k:no es justo dar muerte a un hereje]], pues se traería al mundo una guerra implacable. […] Quiere decir: si toman las armas y matan a los herejes, muchos de los santos [justos] serán derribados con ellos; o bien que de entre la misma cizaña es probable que muchos cambien y se hagan trigo. […] [[a:No prohíbe, pues, que se frene a los herejes, se les tape la boca, se les quite la libertad de palabra y se disuelvan sus asambleas y alianzas; lo que prohíbe es matarlos y degollarlos.]]»',
        work='Homilías sobre el Evangelio de Mateo, hom. 46', date='hacia 390 · griego', ref='Hom. 46, §1 (comentario a Mt 13:28-30, el trigo y la cizaña); numeración NPNF1-10',
        trans=NPNF, url='https://www.newadvent.org/fathers/200146.htm',
        clar='Comentando que el dueño no deja arrancar la cizaña, Crisóstomo da dos razones: se dañaría al trigo (y vendría una guerra implacable) y parte de la cizaña puede convertirse en trigo. Aplica la parábola a los herejes: prohíbe matarlos.',
        ojo='La frase en azul es el matiz que no se puede ocultar: Crisóstomo excluye la muerte, no toda medida contra los herejes (silenciarlos, disolver sus asambleas). Sirve contra la pena de muerte por herejía, no contra toda coacción.'),
  ]),
 dict(id='P02', slug='agustin', name='Agustín de Hipona', dates='354–430', img=f'{HB}/H2/dl/img_augustine.jpg', pos='50% 30%',
  role='Obispo de Hipona (norte de África) desde 395/396. Principal teólogo del Occidente latino y polemista contra los donatistas.',
  why='Es el Padre que más se cita a favor de la coacción religiosa, y también quien pidió que no se ejecutara a los donatistas: el caso que exige más matices.',
  credit='Sandro Botticelli, «San Agustín en su estudio», fresco, h. 1480, iglesia de Ognissanti (Florencia). Wikimedia Commons, «Sandro Botticelli - St Augustine - WGA02709.jpg», dominio público.',
  img_note='Obra renacentista; no hay retrato de Agustín en vida.',
  foot='Citas: Cartas 133 y 185 (NPNF1-01), Sermón del Monte I (NPNF1-06), Carta 93. Traducción al español mía desde el inglés de dominio público; los fragmentos latinos son los que aportó el agente desde la Patrologia Latina (comprobé que están en la página citada; no he leído las cartas en latín). Fechas aproximadas.',
  quotes=[
   dict(theme=['N', 'X'], es='«[…] no queremos que los sufrimientos de los siervos de Dios sean vengados infligiendo exactamente las mismas heridas, a modo de talión. No es que nos opongamos a que se quite a estos malvados la libertad de cometer más crímenes; pero deseamos más bien que la justicia quede satisfecha [[k:sin quitarles la vida ni mutilarles ningún miembro]], y que, [[a:mediante las medidas coercitivas que permitan las leyes]], se les aparte de su frenesí insensato hacia la serenidad de hombres en su sano juicio, o se les obligue a dejar la violencia dañina y a dedicarse a algún trabajo útil.»',
        work='Carta 133 a Marcelino', date='hacia 412 · latín', ref='Carta 133, §1 (NPNF1-01)',
        trans=NPNF, url='https://www.newadvent.org/fathers/1102133.htm',
        orig='…ut vivi et nulla corporis parte truncati, vel ab inquietudine insana ad sanitatis otium legum coercitione dirigantur…',
        clar='Agustín escribe al comisionado imperial Marcelino a favor de donatistas violentos (circunceliones) que habían confesado matar y mutilar a clérigos católicos. Pide que no se les mate ni se les mutile, pero acepta «medidas coercitivas». Es decir: contra la pena de muerte, no contra toda coerción.'),
   dict(theme=['D'], es='«Con todo, es un solo Dios quien, por medio de sus santos profetas y siervos, según una distribución de los tiempos muy ordenada, dio [[k:los preceptos menores]] a un pueblo que aún necesitaba ser atado por el temor; y quien, por medio de su Hijo, dio [[k:los mayores]] a un pueblo al que ya convenía liberar por el amor.»',
        work='Del Sermón del Señor en el monte, libro I', date='hacia 393–396 · latín', ref='Libro I, cap. 1 §2 (numeración NPNF1-06)',
        trans=NPNF, url='https://www.newadvent.org/fathers/16011.htm',
        clar='Un solo Dios y dos etapas: preceptos «menores» para quienes aún se contenían por temor y «mayores» para quienes ya podían ser movidos por el amor. Sobre Mt 5:38-42, Agustín llama a la ley del talión «justicia incompleta, de ningún modo severa, sino misericordiosa», que Cristo lleva «a la perfección» (§57 en esa numeración).'),
   dict(theme=['X', 'N'], es='«Pues ya se había publicado una ley según la cual la herejía de los donatistas, tan salvaje que la misericordia hacia ella suponía en realidad mayor crueldad que su propia locura, [[a:debía ser impedida no solo de ser violenta, sino de existir con impunidad]]; pero [[k:no se le impuso pena capital]], para que incluso con quienes no la merecían se guardara la mansedumbre cristiana: se fijó una multa y se pronunció sentencia de destierro contra sus obispos o ministros.»',
        work='Carta 185 a Bonifacio («Sobre la corrección de los donatistas»)', date='hacia 417 · latín', ref='Carta 185, §26 (NPNF1-01)',
        trans=NPNF, url='https://www.newadvent.org/fathers/1102185.htm',
        orig='…non tamen supplicio capitali, propter servandam etiam circa indignos mansuetudinem christianam, sed pecuniariis damnis propositis, et in episcopos vel ministros eorum exsilio constituto.',
        clar='Agustín describe la ley imperial contra los donatistas y la defiende: multa y destierro, sin pena de muerte, «para que se guarde la mansedumbre cristiana». Es un caso de coerción legal sin ejecución.',
        ojo='Agustín sí defendió la coerción. En la Carta 93 §17 dice que su opinión primera era que nadie fuera obligado a la unidad de Cristo, y que la experiencia la cambió; en la Carta 185 §21-23 defiende ser «primero obligados por el miedo o el dolor» y las leyes «terribles pero saludables»; y en la Carta 93 §10 elogia las leyes imperiales contra los sacrificios paganos, cuya pena es la muerte. Presentarlo como contrario a toda coerción sería falso: sostuvo que a los donatistas no había que ejecutarlos.'),
  ]),
 dict(id='P03', slug='origenes', name='Orígenes', dates='c. 185–c. 253', img=f'{HB}/H3/dl/img_origen.jpg', pos='50% 15%',
  role='Maestro y exégeta de Alejandría y Cesarea. Primer gran comentarista cristiano de la Biblia; su «Contra Celso» responde a un filósofo pagano.',
  why='Argumenta que la ley penal de Moisés, tomada a la letra, no puede regir a los cristianos, y cita Heb 10:29 en sentido moral.',
  credit='Guillaume Chaudière, grabado de 1584 (retrato imaginario). Wikimedia Commons, «Origen.jpg», dominio público.',
  img_note='No existe retrato de Orígenes en vida.',
  foot='Citas: Contra Celso III.7, VII.26, VIII.10 y V.63 (ANF vol. 4). Traducción al español mía desde el inglés de dominio público; no he leído el griego. Fechas aproximadas.',
  ojo='Sobre Hebreos: Eusebio (Hist. ecl. VI.25) le atribuye la frase «quién escribió la epístola, en verdad, Dios lo sabe». No encontré en lo leído a Orígenes citando Heb 10:28, ni ningún texto suyo que pida matar a herejes.',
  quotes=[
   dict(theme=['D', 'H'], es='«[…] es imposible que la legislación de Moisés, tomada al pie de la letra, armonice con la vocación de los gentiles y con su sujeción al gobierno romano; y, por otra parte, sería imposible que los judíos conservaran sin cambio su economía civil si abrazaran el Evangelio. Pues [[k:los cristianos no podrían matar a sus enemigos, ni condenar a ser quemados o apedreados, como manda Moisés,]] a quienes hubieran quebrantado la ley y fueran condenados como merecedores de tales castigos; ya que los propios judíos, por mucho que deseen cumplir su ley, no pueden infligir esos castigos.»',
        work='Contra Celso, libro VII', date='hacia 248 · griego', ref='Libro VII, cap. 26',
        trans=ANF, url='https://www.newadvent.org/fathers/04167.htm',
        clar='Celso había opuesto la no-resistencia del Evangelio a la ley de Moisés. Orígenes responde que la legislación mosaica, a la letra, no cabe en una Iglesia de gentiles bajo gobierno romano: los cristianos «no podrían» ejecutar esas penas. Es un argumento directo de que la ley penal de la Torá no se transfiere a la Iglesia.'),
   dict(theme=['H'], es='«Que el honor que damos al Hijo de Dios, como el que rendimos a Dios Padre, consiste en [[k:una conducta recta de vida]], nos lo enseña claramente el pasaje: “Tú que te glorías de la ley, ¿deshonras a Dios quebrantando la ley?”, y también: “¿De cuánto mayor castigo piensan que será juzgado digno el que ha pisoteado al Hijo de Dios, y ha tenido por cosa impura la sangre de la alianza con que fue santificado, e hizo afrenta al Espíritu de gracia?”»',
        work='Contra Celso, libro VIII', date='hacia 248 · griego', ref='Libro VIII, cap. 10 (cita Rom 2:23 y Heb 10:29)',
        trans=ANF, url='https://www.newadvent.org/fathers/04168.htm',
        clar='Es el único pasaje del pack donde un Padre anterior a Nicea cita Hebreos 10:29 tal cual. Orígenes lo usa para decir que honrar al Hijo es vivir rectamente: una lectura moral, no penal.'),
   dict(theme=['N'], es='«[…] si una revuelta hubiese dado lugar a la república cristiana, derivando así su existencia de la de los judíos, a quienes se permitió tomar las armas en defensa de sus familias y matar a sus enemigos, el Legislador cristiano no habría prohibido por completo dar muerte a los hombres; y sin embargo [[k:en ninguna parte enseña que sea justo que sus discípulos hagan violencia a nadie, por malvado que sea]]. Pues no juzgó acorde con leyes como las suyas, derivadas de una fuente divina, permitir matar a individuo alguno.»',
        work='Contra Celso, libro III', date='hacia 248 · griego', ref='Libro III, cap. 7',
        trans=ANF, url='https://www.newadvent.org/fathers/04163.htm',
        clar='Celso decía que el cristianismo nació como una revuelta judía. Orígenes responde con un condicional: aun en ese caso, el Legislador cristiano no enseña violencia contra nadie. En V.63 aplica Tito 3:10 (rechazar al hereje tras dos amonestaciones) y añade que no se debe odiar a los corruptores del cristianismo.',
        ojo='El texto habla de la violencia de los discípulos en general, no trata del apóstata en particular.'),
  ]),
 dict(id='P04', slug='ireneo', name='Ireneo de Lyon', dates='c. 130–c. 202', img=f'{HB}/H4/dl/img_irenaeus.jpg', pos='50% 20%',
  role='Obispo de Lyon (Galia), de origen griego de Asia Menor. Su «Contra las herejías» defiende que el Dios del Antiguo y del Nuevo Testamento es el mismo.',
  why='Es el testimonio más antiguo del conjunto: el mismo Dios da la Ley «de servidumbre» y el Evangelio de libertad; el Evangelio la cumple y la amplía.',
  credit='Grabado antiguo de autor desconocido. Wikimedia Commons, «Saint Irenaeus.jpg», dominio público (la fecha de la ficha, «s. IV», no la he verificado).',
  img_note='Imagen de baja resolución (245 × 325 px). No hay retrato en vida.',
  foot='Citas: Contra las herejías IV.13.1, IV.16.5, IV.28.1, IV.37.1 (ANF vol. 1). Traducción al español mía desde el inglés de dominio público (la obra se conserva sobre todo en latín); no he leído el original. Fechas aproximadas.',
  ojo='En Contra las herejías no hallé ninguna cita de Heb 10:26-31. Ireneo también escribe que quien llevó leña en sábado fue «justamente apedreado» (IV.8.3) y que los herejes serán quemados por el fuego del cielo (IV.26.2): son castigos divinos narrados o anunciados, no un mandato a la Iglesia.',
  quotes=[
   dict(theme=['D'], es='«[…] no [nos enseñó] esto como cosa contraria a la ley, sino como quien cumple la ley y planta en nosotros la múltiple justicia de la ley. […] no es palabra de quien destruye la ley, sino de quien [[k:la cumple, la extiende y le da mayor amplitud]].»',
        work='Contra las herejías, libro IV', date='hacia 180 · griego (se conserva en latín)', ref='IV.13.1',
        trans=ANF, url='https://www.newadvent.org/fathers/0103413.htm',
        clar='Sobre el Sermón del Monte («han oído que se dijo… pero yo les digo»): Cristo no se opone a la Ley; la cumple y le da mayor alcance, prohibiendo incluso el deseo. Es la imagen de la «plenitud».'),
   dict(theme=['D'], es='«Las leyes de servidumbre, en cambio, fueron promulgadas al pueblo una a una por Moisés, adecuadas a su instrucción o a su castigo, como el propio Moisés declaró: “Y el Señor me mandó en aquel tiempo enseñarles estatutos y juicios”. Estas cosas, pues, que fueron dadas para la servidumbre y como señal para ellos, [[k:las canceló por la nueva alianza de libertad]].»',
        work='Contra las herejías, libro IV', date='hacia 180 · griego (se conserva en latín)', ref='IV.16.5 (cita Dt 4:14)',
        trans=ANF, url='https://www.newadvent.org/fathers/0103416.htm',
        clar='Las leyes de Moisés eran «de servidumbre», dadas para instruir o castigar a un pueblo en esa condición, y la nueva alianza de libertad las canceló. Ireneo exceptúa el Decálogo, que no fue cancelado.'),
   dict(theme=['P'], es='«Como en ambos Testamentos hay la misma justicia de Dios cuando Dios toma venganza —en el uno, ciertamente, [[k:de modo típico, temporal y más moderado]]; en el otro, [[k:real, duradero y más severo]]: porque el fuego es eterno, y la ira de Dios que se revelará desde el cielo […] acarrea un castigo más pesado a quienes la incurren— […] ellos [los ancianos] señalaron que están faltos de sentido quienes pretenden introducir otro Padre.»',
        work='Contra las herejías, libro IV', date='hacia 180 · griego (se conserva en latín)', ref='IV.28.1',
        trans=ANF, url='https://www.newadvent.org/fathers/0103428.htm',
        clar='Es el razonamiento paralelo a Heb 10:28-29, sin citarlo: la misma justicia, de menos a más. La venganza que se ve en el Antiguo Testamento es «típica y moderada»; la del Nuevo es «real y eterna». Es decir: el castigo mayor del Evangelio es divino y último, no un castigo humano.'),
   dict(theme=['N'], es='«Dios hizo al hombre libre desde el principio, poseedor de su propio poder, como de su propia alma, para obedecer los mandatos de Dios voluntariamente y no por compulsión de Dios. [[k:Pues en Dios no hay coacción]], sino que su buena voluntad hacia nosotros está siempre presente.»',
        work='Contra las herejías, libro IV', date='hacia 180 · griego (se conserva en latín)', ref='IV.37.1',
        trans=ANF, url='https://www.newadvent.org/fathers/0103437.htm',
        clar='Habla de Dios y la libertad humana, no del trato a los herejes: es un principio, no una norma sobre el poder civil. Más abajo, el mismo párrafo dice que los desobedientes recibirán «el castigo merecido» de Dios.'),
  ]),
 dict(id='P05', slug='tertuliano', name='Tertuliano de Cartago', dates='c. 155–c. 220', img=f'{HB}/H5/dl/img_tertullian.jpg', pos='50% 20%',
  role='Escritor latino de Cartago, apologista y polemista; en su última etapa se acercó al montanismo.',
  why='Defendió la libertad de religión para los cristianos y argumentó que la Ley antigua frenaba la violencia y fue superada por la clemencia del Evangelio; pero también cita sin reparos castigos del Antiguo Testamento.',
  credit='André Thevet, grabado de 1584 (retrato imaginario). Wikimedia Commons, «Tertullian.jpg», dominio público.',
  img_note='No existe retrato de Tertuliano en vida.',
  foot='Citas: A Escápula 2, Contra los judíos 3, Contra Marción II.18 (ANF vol. 3). Traducción al español mía desde el inglés de dominio público; los fragmentos latinos coinciden con The Latin Library (comprobado). Fechas aproximadas.',
  ojo='Hebreos: en Sobre el pudor 20 cita Heb 6:4-6 como «la Epístola a los Hebreos, bajo el nombre de Bernabé» (obra de su etapa montanista); no hallé a Tertuliano citando Heb 10:26-31. Casos en contra: en Scorpiace 2 cita Dt 13 (apedrear al que aparta de Dios) como mandato divino contra la idolatría y en Scorpiace 3 relata sin reproche los 23.000 muertos «por las espadas de sus compatriotas»; en Contra Marción II.28 defiende la severidad del Dios del Antiguo Testamento («Mi Dios ordenó matar a un hombre»). No dice que la Iglesia deba ejecutarlo.',
  quotes=[
   dict(theme=['N'], es='«Es un derecho humano fundamental, un privilegio de la naturaleza, que cada uno adore según sus convicciones: la religión de uno no daña ni favorece a otro. Ciertamente [[k:no forma parte de la religión obligar a la religión]] —a la que debe llevarnos el libre albedrío y no la fuerza—, pues incluso las víctimas de los sacrificios se piden de un ánimo voluntario. No harán ningún servicio real a sus dioses obligándonos a sacrificar.»',
        work='A Escápula (Ad Scapulam)', date='hacia 212 · latín', ref='Cap. 2',
        trans=ANF, url='https://www.newadvent.org/fathers/0305.htm',
        orig='Sed nec religionis est cogere religionem, quae sponte suscipi debeat, non ui…',
        clar='Tertuliano se dirige al procónsul de Cartago para que cese la persecución de los cristianos. Es un argumento general sobre la libertad de culto; no se refiere a herejes ni a apóstatas.'),
   dict(theme=['D'], es='«Pues la costumbre de la ley antigua era vengarse con la venganza de la espada, sacar ojo por ojo e infligir revancha por la injuria. Pero la costumbre de la ley nueva era apuntar a la clemencia y [[k:convertir en tranquilidad la ferocidad primitiva de las espadas y las lanzas]], y transformar la ejecución primitiva de la guerra contra los rivales y enemigos de la ley en las acciones pacíficas de arar y labrar la tierra.»',
        work='Respuesta a los judíos (Adversus Iudaeos)', date='hacia 200 · latín', ref='Cap. 3 (sección latina 10)',
        trans=ANF, url='https://www.newadvent.org/fathers/0308.htm',
        clar='A partir de Isaías 2:3-4 («forjarán arados de sus espadas»), Tertuliano contrapone la ley antigua, «obliterada», que se vengaba con la espada, y la nueva, que apunta a la clemencia.',
        ojo='La obra es polémica contra el judaísmo; uso este párrafo solo por el contraste entre las dos leyes.'),
   dict(theme=['D', 'P'], es='«Aquí no hay ni rastro de permiso para el daño mutuo, sino más bien [[k:una disposición para frenar la violencia]]. A un pueblo muy obstinado y falto de fe en Dios podía parecerle largo, e incluso increíble, esperar de Dios aquella venganza que después había de declarar el profeta: “Mía es la venganza; yo daré el pago, dice el Señor”.»',
        work='Contra Marción, libro II', date='hacia 207 · latín', ref='II.18.1 (sobre el talión, Éx 21:24)',
        trans=ANF, url='https://www.newadvent.org/fathers/03122.htm',
        orig='…sed in totum cohibendae violentiae prospicit, ut quia durissimo et infideli in deum populo longum vel etiam incredibile videretur a deo expectare defensam…',
        clar='Contra Marción, que llamaba cruel a la Ley, Tertuliano explica el talión como freno de la venganza para un pueblo «obstinado», antes de que se declarara «Mía es la venganza» (el texto que Hebreos 10:30 también cita). Es la idea de la «moral contextualizada».'),
  ]),
 dict(id='P06', slug='lactancio', name='Lactancio', dates='c. 250–c. 320', img=f'{HB}/IMG/lactance.jpg', pos='50% 25%',
  role='Retórico latino convertido al cristianismo, consejero del emperador Constantino. Su «Instituciones divinas» es la primera exposición sistemática del cristianismo en latín.',
  why='Es el testimonio más claro de la libertad religiosa en los Padres latinos: «la religión no puede imponerse por la fuerza» y matar «siempre es ilícito».',
  credit='Henri Bonnart (I o II), grabado. Wikimedia Commons, «Lactance, PA01382.jpg», dominio público.',
  img_note='Retrato imaginario de estilo barroco (la leyenda dice «Lactance»); no es de su tiempo.',
  foot='Citas: Instituciones divinas V.20, VI.20, IV.20 (ANF vol. 7). Traducción al español mía desde el inglés de dominio público; los fragmentos latinos coinciden con el texto latino de Wikisource (comprobado). Fechas aproximadas.',
  ojo='Lactancio no cita Hebreos en lo leído (la referencia «Heb 10:30» que aparece en VI.18 es una nota del editor inglés, no de Lactancio). Sus textos sobre la fuerza se dirigen a la persecución pagana de los cristianos, no tratan de herejes, aunque enuncian el principio general. Casos en contra: en V.8 imagina un mundo sin «cárceles ni espadas de los gobernantes» y en Sobre la muerte de los perseguidores 47 presenta la derrota de un perseguidor como castigo de Dios.',
  quotes=[
   dict(theme=['N'], es='«No hay lugar para la violencia ni el daño, pues [[k:la religión no puede imponerse por la fuerza]]; el asunto ha de llevarse con palabras más que con golpes, para que se mueva la voluntad. […] Porque la religión se ha de defender no matando, sino muriendo; no con crueldad, sino con paciente aguante; no con culpa, sino con buena fe. […] Pues si quieren defender la religión con derramamiento de sangre, con tormentos y con culpa, ya no será defendida, sino contaminada y profanada. Porque [[k:nada hay tan propio del libre albedrío como la religión]]; si en ella el ánimo del que adora no está dispuesto, la religión queda al instante suprimida y deja de existir.»',
        work='Instituciones divinas, libro V', date='hacia 304–313 · latín', ref='V.20 (latín V.19.11 y 19.22-23)',
        trans=ANF, url='https://www.newadvent.org/fathers/07015.htm',
        orig='…religio cogi non potest, uerbis potius quam uerberibus res agenda est… nihil est enim tam uoluntarium quam religio…',
        clar='Lactancio se dirige a Constantino y reta a sacerdotes y filósofos paganos a argumentar sin violencia. El principio —la fe obligada deja de ser fe— está enunciado en general.'),
   dict(theme=['N'], es='«Cuando Dios nos prohíbe matar, no solo nos veda la violencia abierta, que ni siquiera permiten las leyes públicas, sino que nos advierte contra aquello que entre los hombres se tiene por lícito. Así, ni será lícito al justo hacer la guerra, pues su guerra es la justicia misma, ni acusar a nadie de un delito capital, porque da lo mismo matar a un hombre con la palabra que con la espada, ya que lo prohibido es el acto mismo de matar. Por tanto, respecto de este precepto de Dios, [[k:no debe haber excepción alguna: siempre es ilícito matar a un hombre]], a quien Dios quiso que fuera un animal sagrado.»',
        work='Instituciones divinas, libro VI', date='hacia 304–313 · latín', ref='VI.20 (latín VI.20.15-17)',
        trans=ANF, url='https://www.newadvent.org/fathers/07016.htm',
        clar='Lactancio extrae del «No matarás» una prohibición sin excepciones: no solo el homicidio, también la guerra y la acusación capital. Es la posición más estricta del pack, y se aparta de lo que luego aceptó la mayoría.'),
   dict(theme=['D'], es='«Pues lo que dijo antes —que haría un nuevo testamento con la casa de Judá— muestra que [[k:el antiguo testamento, el que fue dado por Moisés, no era perfecto]]; pero que el que había de ser dado por Cristo sería completo.»',
        work='Instituciones divinas, libro IV', date='hacia 304–313 · latín', ref='IV.20 (latín IV.20.10; glosa de Jr 31:31)',
        trans=ANF, url='https://www.newadvent.org/fathers/07014.htm',
        orig='…ostendit uetus illut testamentum quod per Moysen datum est non fuisse perfectum, id autem quod per Christum dari haberet consummatum fore.',
        clar='Es lo más cercano en Lactancio a la tesis del vídeo reformulada: el testamento de Moisés «no era perfecto»; el de Cristo, «completo». Lo dice como glosa de Jeremías 31, no de Hebreos.'),
  ]),
 dict(id='P07', slug='atanasio', name='Atanasio de Alejandría', dates='c. 296–373', img=f'{HB}/H7/dl/img_athanasius.jpg', pos='50% 15%',
  role='Obispo de Alejandría. Campeón de Nicea contra los arrianos; desterrado cinco veces por emperadores que apoyaban a sus rivales.',
  why='Perseguido él mismo por la fuerza imperial, escribe la defensa más directa de que la verdad se predica «con persuasión y consejo», no con espadas.',
  credit='Icono bizantino de autor desconocido. Wikimedia Commons, «Ikone Athanasius von Alexandria.jpg», dominio público.',
  img_note='Iconografía tradicional, no un retrato en vida.',
  foot='Citas: Historia de los arrianos §33 y §67; Sobre la encarnación §40 (NPNF2-04). Traducción al español mía desde el inglés de dominio público; el griego de §33 coincide con el texto de la Patrologia Graeca 25 (OCR de archive.org; comprobado). Fechas aproximadas.',
  ojo='Sobre Hebreos: Atanasio comenta Heb 3:1-2 en el Discurso II contra los arrianos §9 y cita Heb 7:19 en otro lugar; no hallé Heb 10:26-31. Casos en contra: en Sobre los decretos §28 pregunta retóricamente «¿quién no apedrearía a tales locos?» (contra los arrianos, sin pedirlo como norma), y en la Apología a Constancio §30 reproduce una carta del emperador que ordena matar a sus partidarios, para denunciarla.',
  quotes=[
   dict(theme=['N'], es='«Pero nuestro Salvador es tan manso que enseña así: “Si alguno quiere venir en pos de mí”, y “El que quiera ser mi discípulo”; y viniendo a cada uno no lo obliga, sino que llama a la puerta y dice: “Ábreme, hermana mía, esposa mía”; y si le abren, entra, pero si se demoran y no quieren, se aparta de ellos. [[k:Porque la verdad no se predica con espadas ni con dardos, ni por medio de soldados, sino con persuasión y consejo.]]»',
        work='Historia de los arrianos', date='hacia 358–362 · griego', ref='§33 («La persecución viene del diablo»); cita Mt 16:24 y Cant 5:2',
        trans=NPNF, url='https://www.newadvent.org/fathers/28154.htm',
        orig='Οὐ γὰρ ξίφεσιν, ἢ βέλεσιν, οὐδὲ διὰ στρατιωτῶν ἡ ἀλήθεια καταγγέλλεται, ἀλλὰ πειθοῖ καὶ συμβουλίᾳ.',
        clar='Atanasio contrapone al diablo, que derriba las puertas con hachas y martillos, a Cristo, que llama y no fuerza. Lo dice contra los arrianos, que usaban la fuerza imperial contra los ortodoxos.'),
   dict(theme=['N'], es='«[…] esta moderna y maldita herejía, cuando es derribada por argumentos, procura enseguida coaccionar con violencia, golpes y cárcel a aquellos a quienes no ha podido persuadir con razones, reconociendo con ello que es cualquier cosa menos piadosa. Pues es propio de la verdadera piedad [[k:no obligar, sino persuadir]], como dije antes. Así nuestro Señor mismo, no empleando la fuerza sino ofreciéndolo a su libre elección, dijo a todos: “Si alguno quiere seguirme”; y a sus discípulos: “¿También ustedes quieren irse?”»',
        work='Historia de los arrianos', date='hacia 358–362 · griego', ref='§67 (cita Mt 16:24 y Jn 6:67)',
        trans=NPNF, url='https://www.newadvent.org/fathers/28158.htm',
        clar='Para Atanasio, usar la violencia con quien no se deja persuadir es señal de que una herejía no es «piadosa»: es lo que hacía el partido arriano con Constancio. Lo aplica a la fe, no al delito común.'),
   dict(theme=['D'], es='«Pues cuando vino Aquel a quien se señalaba, ¿qué necesidad había ya de que alguien lo señalara? Estando la verdad presente, [[k:¿qué necesidad había ya de la sombra?]] Porque esta era la razón de que profetizaran: hasta que viniera la verdadera Justicia y Aquel que había de rescatar los pecados de todos. Y por eso estuvo en pie Jerusalén hasta entonces: para que allí se ejercitaran en los tipos como preparación para la realidad.»',
        work='Sobre la encarnación del Verbo', date='hacia 318 · griego', ref='§40',
        trans=NPNF, url='https://www.newadvent.org/fathers/2802.htm',
        clar='Es el lenguaje de Hebreos 10:1 («sombra de los bienes futuros»), aunque Atanasio no cita ese versículo aquí: la profecía y los tipos eran preparación hasta que viniera la realidad.'),
  ]),
 dict(id='P08', slug='jeronimo', name='Jerónimo', dates='c. 347–420', img=f'{HB}/IMG/jerome_stom.jpg', pos='50% 30%',
  role='Monje y erudito de Belén. Traductor de la Vulgata y exégeta; autor de numerosas cartas y polémicas.',
  why='Es el Padre que más matiza: describe con claridad el paso de la espada de la ley antigua a la «espada espiritual», pero en otra carta invoca Dt 13 para justificar el celo violento.',
  credit='Matthias Stom, «San Jerónimo penitente», pintura del s. XVII, Musée d’arts de Nantes. Wikimedia Commons, «MatthiasStom-SaintJerome-Nantes.jpg», dominio público (PD-old-100, según Commons).',
  img_note='Pintura barroca; no hay retrato de Jerónimo en vida.',
  foot='Citas: Cartas 14, 22 y 109 (NPNF2-06). Traducción al español mía desde el inglés de dominio público; no he leído el latín de estas cartas. Fechas aproximadas.',
  ojo='Hebreos: en las cartas que leí Jerónimo cita Hebreos pero no 10:26-31. Aquino atribuye a Jerónimo (Comentario a Gálatas 5:9, según el Decreto de Graciano) «hay que cortar las carnes podridas…»; el Manipulus florum lo cita en Jerónimo, In Gal. III (CCSL 77A, p. 163), pero ni el agente ni yo hemos abierto esa edición: no lo uso como cita verificada.',
  quotes=[
   dict(theme=['D'], es='«Bajo la ley antigua, el que desobedecía a los sacerdotes era puesto fuera del campamento y apedreado por el pueblo, o bien era decapitado y expiaba su desprecio con su sangre. Pero ahora [[k:el desobediente es abatido con la espada espiritual, o es expulsado de la Iglesia]] y despedazado por demonios rapaces.»',
        work='Carta 14 a Heliodoro', date='hacia 373–374 · latín', ref='Carta 14, §8 (cita Dt 17:5, 12)',
        trans=NPNF, url='https://www.newadvent.org/fathers/3001014.htm',
        clar='Jerónimo toma la misma ley de Dt 17 que está detrás de Heb 10:28 y dice cómo se aplica «ahora»: no con piedras, sino con la «espada espiritual» o la expulsión de la Iglesia. Habla de la obediencia monástica y lo dice en sentido figurado.'),
   dict(theme=['D'], es='«La ley antigua tenía otro ideal de bienaventuranza […]. Pero ahora incluso a los eunucos se les dice: “No digas: he aquí que soy un árbol seco”, pues en lugar de hijos e hijas tienes un lugar para siempre en el cielo. [[k:Ahora los pobres son bienaventurados]], ahora Lázaro es puesto delante del rico vestido de púrpura. Ahora el débil es tenido por fuerte.»',
        work='Carta 22 a Eustoquio', date='384 · latín', ref='Carta 22, §21 (cita Is 56:3)',
        trans=NPNF, url='https://www.newadvent.org/fathers/3001022.htm',
        clar='Jerónimo contrasta lo que la ley antigua llamaba bendición (hijos, riquezas) con el ideal del Evangelio. Es la distinción en el plano moral; no trata de penas.'),
   dict(theme=['X'], es='«[[a:No hay crueldad en el celo por el honor de Dios.]] Por eso también en la Ley se dice: “Si tu hermano, tu amigo o la mujer de tu seno te seduce [apartándote] de la verdad, tu mano estará sobre ellos y derramarás su sangre”, “y así quitarás el mal de en medio de Israel”.»',
        work='Carta 109 a Ripario (contra Vigilancio)', date='hacia 404 · latín', ref='Carta 109, §3 (cita Dt 13:6-9)',
        trans=NPNF, url='https://www.newadvent.org/fathers/3001109.htm',
        clar='Jerónimo escribe contra Vigilancio, que criticaba el culto a las reliquias. Invoca Fineas, Elías y la Ley de Dt 13 para decir que el celo por Dios no es crueldad. Es su propia voz, no una cita ajena.',
        ojo='Es el texto más adverso del pack. No pide que el Estado ejecute a Vigilancio, pero en §2 dice que su obispo debería «entregarlo a la destrucción de la carne» (1 Co 5:5, fórmula ambigua) y que «habría que cortarle la lengua o tratarlo por locura». No cita Heb 10:28.'),
  ]),
]
